private readonly cache = new Map<string, { expires: number; value$: Observable<Customer> }>();

getCustomer(id: string) {
  const now = Date.now();
  const hit = this.cache.get(id);
  if (hit && hit.expires > now) return hit.value$;

  const value$ = this.http.get<Customer>(`/api/customers/${id}`).pipe(
    shareReplay({ bufferSize: 1, refCount: false }),
    catchError(error => { this.cache.delete(id); return throwError(() => error); })
  );
  this.cache.set(id, { expires: now + 30_000, value$ });
  return value$;
}

