uploadChunk(file: File, start: number, size: number, uploadId: string) {
  const chunk = file.slice(start, start + size);
  return this.http.put(`/api/uploads/${uploadId}/chunks/${start}`, chunk, {
    observe: 'events', reportProgress: true
  });
}

createExport(query: TransactionQuery) {
